{"variables":{"handle":"lightweight-cotton-quilt-set"},"query":"query ProductCard($handle: String!) {
  product(handle: $handle) {
    title
    id
    onlineStoreUrl
    priceRange{
      minVariantPrice {
        amount
      }
    }
    options(first: 3) {
      name
      values
    }
    variants(first: 1) {
      edges {
        node {
          ...variantData
        }
      }
    }
    tags
    shortDescription: metafield(namespace: "acf_pdp", key: "description_short") {
      value
    }
    fromPrice: metafield(namespace: "acf_pdp", key: "from_price") {
      value
    }
  }
}fragment variantData on ProductVariant {
  id
  image {
    altText
    url(transform: {maxWidth: 800})
  }
  compareAtPrice {
    amount
  }
  price {
    amount
  }
}"}

