{"variables":{"handle":"luxe-core-sheet-set"},"query":"query ProductGallery($handle: String!) {
  product(handle: $handle) {
    media(first: 250) {
        edges {
            node {
                alt
                ... on MediaImage {
                    image {
                        url(
                            transform: { maxWidth: 768, crop: CENTER, preferredContentType: WEBP }
                        )
                    }
                }
                ... on MediaImage {
                  zoom: image {
                      url(
                          transform: { maxWidth: 1024, crop: CENTER }
                      )
                  }
                }
                ... on Video {
                    previewImage {
                        url(
                            transform: { maxWidth: 768, crop: CENTER, preferredContentType: WEBP }
                        )
                    }
                    sources {
                        url
                        mimeType
                    }
                }
            }
        }
    }
    image_gallery_infographic: metafield(namespace: "custom", key: "infographic") {
      metaobjects: references(first: 10) {
        nodes {
          ... on Metaobject {
            id
            fields {
              key
              value

              object: reference {
                ... on MediaImage {
                  image {
                    id
                    url (transform: { maxWidth: 768, crop: CENTER, preferredContentType: WEBP })
                    zoom: url (transform: { maxWidth: 1024, crop: CENTER })
                  }
                }
              }
            }
          }
        }
      }
    }
    image_gallery_video: metafield(namespace: "custom", key: "image_gallery_video") {
      metaobjects: references(first: 10) {
        nodes {
          ... on Metaobject {
            fields {
              key
              value

              object: reference {
                ... on MediaImage {
                  image {
                    id
                    url
                  }
                }
                ... on GenericFile {
                  url
                }
              	... on Video {
                  sources {
                    url
                  }
                  previewImage {
                    url
                  }
                }
              }
            }
          }
        }
      }
    }
  }
}"}

