{"variables":{"handle":"linen-core-sheet-set"},"query":"query Product($handle: String!) {
  product(handle: $handle) {
    title
    tags
    handle
    id
    onlineStoreUrl
    priceRange {
      minVariantPrice {
        amount
      }
    }
    options {
      name
      values
    }
    variants(first: 100) {
      edges {
        node {
          id
          product {
            id
          }
          quantityAvailable
          sku
          selectedOptions {
            value
            name
          }
          price {
            amount
          }
          compareAtPrice {
            amount
          }
          shipsBy: metafield(namespace: "acf_variant", key: "ships_by") {
            value
          }
        }
      }
    }
    upsell_products: metafield(key: "upsell_products", namespace: "acf_pdp") {
      value
    }
    shortDescription: metafield(namespace: "acf_pdp", key: "description_short") {
      value
    }
    textBadge: metafield(namespace: "acf_pdp", key: "badge_text") {
      value
    }
    imageBadge: metafield(namespace: "acf_pdp", key: "badge_asset") {
      value
    }
    fromPrice: metafield(namespace: "acf_pdp", key: "from_price") {
      value
    }
  }
}"}

{"variables":{"handle":"linen-core-sheet-set"},"query":"query ProductGallery($handle: String!) {
  product(handle: $handle) {
    media(first: 250) {
        edges {
            node {
                alt
                ... on MediaImage {
                    image {
                        url(
                            transform: { maxWidth: 768, crop: CENTER, preferredContentType: WEBP }
                        )
                    }
                }
                ... on MediaImage {
                  zoom: image {
                      url(
                          transform: { maxWidth: 1024, crop: CENTER }
                      )
                  }
                }
                ... on Video {
                    previewImage {
                        url(
                            transform: { maxWidth: 768, crop: CENTER, preferredContentType: WEBP }
                        )
                    }
                    sources {
                        url
                        mimeType
                    }
                }
            }
        }
    }
    image_gallery_infographic: metafield(namespace: "custom", key: "infographic") {
      metaobjects: references(first: 10) {
        nodes {
          ... on Metaobject {
            id
            fields {
              key
              value

              object: reference {
                ... on MediaImage {
                  image {
                    id
                    url (transform: { maxWidth: 768, crop: CENTER, preferredContentType: WEBP })
                    zoom: url (transform: { maxWidth: 1024, crop: CENTER })
                  }
                }
              }
            }
          }
        }
      }
    }
    image_gallery_video: metafield(namespace: "custom", key: "image_gallery_video") {
      metaobjects: references(first: 10) {
        nodes {
          ... on Metaobject {
            fields {
              key
              value

              object: reference {
                ... on MediaImage {
                  image {
                    id
                    url
                  }
                }
                ... on GenericFile {
                  url
                }
              	... on Video {
                  sources {
                    url
                  }
                  previewImage {
                    url
                  }
                }
              }
            }
          }
        }
      }
    }
  }
}"}

